arguments.command:
python3 -I - <<'EOF'
import json, hashlib, os
# Verify current on-disk state vs manifest (stale paths) and catalog (current paths)
root = '/workspace/incident/dataset'
man = json.load(open(f'{root}/manifest.json'))
cat = json.load(open(f'{root}/catalog.json'))
def sha(p):
    return hashlib.sha256(open(p,'rb').read()).hexdigest()
man_ok = man_missing = 0
cat_ok = cat_missing = 0
for rows, name in ((man['rows'],'manifest'), (cat['rows'],'catalog')):
    ok = missing = mismatch = 0
    for r in rows:
        p = os.path.join(root, r['path'])
        if not os.path.isfile(p):
            missing += 1
        elif sha(p) == r['sha256']:
            ok += 1
        else:
            mismatch += 1
    print(f"{name}: ok={ok} missing={missing} mismatch={mismatch} total={len(rows)}")
EOF

