import json, collections
# incident events: which paths were read at each step (steps 0-3, arm healthy)
by_step = collections.defaultdict(set)
with open('/workspace/incident/run/events.jsonl') as f:
    for line in f:
        try: e = json.loads(line)
        except Exception: continue
        if e.get('kind') == 'read':
            by_step[e['step']].add(e['path'])
for s in sorted(by_step):
    paths = sorted(by_step[s])
    live_hard = [p for p in paths if p.startswith('live/hard')]
    print(f"step {s}: {len(paths)} distinct paths; live/hard count = {len(live_hard)}")
    if s == 3:
        for p in live_hard[:4]: print("   ", p)
EOF

