arguments.content:
"""Resolve a logical training record to its backing file.

A record pins the content it needs by ``sha256``. The dataset root keeps
sample files under per-difficulty directories (``live/<difficulty>/`` and,
after a relocation, ``archive/<difficulty>/``); each file is named
``<id>.json`` and stores the pinned digest at the top level. Resolution is a
bounded content query: locate the file whose pinned digest matches the
record's ``sha256`` and return its path relative to the dataset root. When no
matching content can be located, the record is unavailable and a
``FileNotFoundError`` is raised instead of returning any path.
"""

import json
from pathlib import Path


def resolve(root, record):
    digest = record.get("sha256")
    if digest is None:
        raise ValueError("record pins no sha256")
    base = Path(root)
    candidates = []
    record_id = record.get("id")
    difficulty = record.get("difficulty")
    if record_id is not None and difficulty is not None:
        name = str(record_id) + ".json"
        candidates.append(Path("live").joinpath(str(difficulty)).joinpath(name))
        candidates.append(Path("archive").joinpath(str(difficulty)).joinpath(name))
    path = record.get("path")
    if path is not None:
        candidates.append(Path(str(path)))
        # Relocation fallback: content moved live/<difficulty> -> archive/<difficulty>.
        if str(path).startswith("live/"):
            candidates.append(Path(str(path).replace("live/", "archive/", 1)))
    ids = []
    if record_id is not None:
        ids.append(str(record_id))
    ids.append(str(digest))
    for sub in ["live", "archive"]:
        for level in ["easy", "hard"]:
            for stem in ids:
                candidates.append(Path(sub).joinpath(level).joinpath(stem + ".json"))
    seen = []
    for candidate in candidates:
        if str(candidate) in seen:
            continue
        seen.append(str(candidate))
        target = base.joinpath(candidate)
        if not target.is_file():
            continue
        try:
            data = json.loads(target.read_text())
        except ValueError:
            continue
        if data.get("sha256") == digest:
            return str(candidate)
    raise FileNotFoundError("no content matching sha256 " + str(digest))

